\begin{abstract}
We study a deductive system through its \emph{counting data}: the cumulative number $N(n)$ of derivable statements of encoded length at most $n$, measured against the ambient volume $S_k(n)=\sum_{i\le n}k^i$ of the $k$-letter language. Two encodings of the same system that translate into one another with additive length overhead at most $b$ distort metric balls by a radial shift of at most $b$. We determine precisely which observables survive such a \emph{bounded recoding}.

Two survive: the \emph{count radius} $r(m)=\min\{n: N(n)\ge m\}$ is $b$-quasi-invariant, and the \emph{entropy dimension} $h=\lim_n \log N(n)/n$ is exactly invariant. The density level is not. We prove the splitting identity $S_k(n+b)=\sum_{i<b}k^i+k^bS_k(n)$, hence $S_k(n+b)\le 2k^bS_k(n)$ and the distortion law $d_1(n)\le 2k^b d_2(n+b)$: recodings act additively on radii but multiplicatively on levels. This gives a critical-index sandwich across rescaled levels, and we show the rescaling is unavoidable: for every $D$ there are antitone null profiles obeying exactly the distortion inequalities of an overhead-$1$ binary recoding whose same-level critical indices differ by at least $D$.

Sharpness is restored by exponential order: if $ca^n\le N(n)\le Ca^n$ with $a<k$, any radius where the density is still at level $\varepsilon$ and any radius where it has dropped below $\varepsilon$ are separated by at most $\log(2C/c)/\log(k/a)$, independently of $\varepsilon$. Cross-system, this bounds the gap between the critical indices of two encodings uniformly in $\varepsilon$; an overhead-$b$ recoding perturbs the constants only by $a^{\pm b}$. For counts submultiplicative up to a factor $P$, Fekete's lemma supplies the matching lower bound $e^{Ln}\le PN(n)$ and an unconditional window bound $\log(2CP)/\log(k/e^L)$.

We then develop the \emph{dimension spectrum}: every $h\in[0,\log k]$ is the entropy dimension of a genuine subfamily, of ambient density zero whenever $e^h<k$; unions take the maximum dimension; strata meeting independently in the counting sense intersect in dimension $h_1+h_2-\log k$, strictly below both when both are proper. Finally, a single proof regime of entropy $s$ has tail $e^{-sx}$ with the constant successive ratio $e^{-s}$, so no power law arises homogeneously; the uniform scale mixture over $s\in[0,1]$ has the exact tail $(1-e^{-x})/x$, a power law of index $-1$ with successive ratios tending to $1$ and no geometric dominating bound.
\end{abstract}

\section{Introduction}

\subsection{Counting a deductive system}

Fix a finite alphabet with $k\ge 2$ letters and a prefix-free encoding of the statements of a deductive system as finite strings; write $|\varphi|$ for the encoded length. The set of statements of length at most $n$ is a ball in the string metric of cardinality
\[
S_k(n)\;=\;\sum_{i=0}^{n}k^{i}\;=\;\frac{k^{n+1}-1}{k-1}.
\]
Two elementary facts are used throughout: $k^n\le S_k(n)$ and, for $k\ge2$, $S_k(n)\le 2k^n$. Thus $S_k(n)\asymp k^n$ within a factor $2$.

Let $N(n)$ be the number of derivable statements of length at most $n$.

\begin{definition}[Derivability density]
$\dens_N(n)=N(n)/S_k(n)$.
\end{definition}

\begin{definition}[Entropy dimension]
A count $N$ \emph{has entropy dimension} $h$ if $\log N(n)/n\to h$ as $n\to\infty$.
\end{definition}

The ambient count has entropy dimension $\log k$; a system is \emph{exponentially sparse} when its dimension is strictly smaller, and then $\dens_N(n)\to0$.

\subsection{The recoding problem}

Neither $N$ nor $\dens_N$ is intrinsic: both depend on the encoding.

\begin{definition}[Bounded recoding of overhead $b$]
Two encodings of the same system are related by a recoding of overhead $b$ if there are injections translating each into the other with $|\tau(\varphi)|_2\le|\varphi|_1+b$ and $|\sigma(\psi)|_1\le|\psi|_2+b$.
\end{definition}

\begin{proposition}[Balls shift radially]
Let $B_i(n)$ be the ball of radius $n$ in encoding $i$ and $f$ an injection with $|f(x)|_2\le|x|_1+b$. Then $|B_1(n)|\le|B_2(n+b)|$ for all $n$.
\end{proposition}

\begin{proof}
$f$ maps $B_1(n)$ injectively into $B_2(n+b)$, since $|x|_1\le n$ implies $|f(x)|_2\le n+b$.
\end{proof}

For counting functions this reads
\begin{equation}\label{eq:star}
N_1(n)\le N_2(n+b),\qquad N_2(n)\le N_1(n+b)\qquad(n\in\N),
\end{equation}
a quasi-isometry with multiplicative constant $1$ and additive constant $b$. Condition \eqref{eq:star} is our standing abstraction of ``same system, different writing''.

\section{Invariant observables}

\subsection{Count radii}

\begin{definition}[Count radius]
For a nondecreasing $N:\N\to\N$ and $m\in\N$, let $r_N(m)=\min\{n\in\N: m\le N(n)\}$. This is the observable dual to a density level: fix a count and read off a radius.
\end{definition}

\begin{theorem}[Radial quasi-invariance]\label{thm:radial}
Assume \eqref{eq:star} and that each $N_i$ attains $m$. Then $|r_{N_1}(m)-r_{N_2}(m)|\le b$.
\end{theorem}

\begin{proof}
By definition $m\le N_1(r_{N_1}(m))\le N_2(r_{N_1}(m)+b)$, so $r_{N_2}(m)\le r_{N_1}(m)+b$. Swap the systems.
\end{proof}

\subsection{Exact invariance of the entropy dimension}

\begin{lemma}[Shift invariance of growth rates]\label{lem:shift}
If $\log N(n)/n\to h$ then $\log N(n+b)/n\to h$ for each fixed $b$.
\end{lemma}

\begin{proof}
$\frac{\log N(n+b)}{n}=\frac{\log N(n+b)}{n+b}\cdot\frac{n+b}{n}$; the first factor tends to $h$ and the second to $1$.
\end{proof}

\begin{theorem}[Exact invariance of the entropy dimension]\label{thm:dim-inv}
Suppose $N_1,N_2\ge1$ pointwise satisfy \eqref{eq:star} and have entropy dimensions $h_1,h_2$. Then $h_1=h_2$.
\end{theorem}

\begin{proof}
For $n\ge1$, $\log N_1(n)/n\le \log N_2(n+b)/n$; let $n\to\infty$ and use Lemma~\ref{lem:shift} to get $h_1\le h_2$. Symmetry gives the reverse.
\end{proof}

\section{Density distortion and the failure of same-level stability}

\begin{lemma}[Exact splitting]\label{lem:split}
$S_k(n+b)=\bigl(\sum_{i<b}k^{i}\bigr)+k^{b}S_k(n)$.
\end{lemma}

\begin{proof}
Split $\{0,\dots,n+b\}$ as $\{0,\dots,b-1\}\sqcup\{b,\dots,b+n\}$ and factor $k^b$ out of the second block.
\end{proof}

\begin{lemma}\label{lem:vol}
For $k\ge2$: $\sum_{i<b}k^i\le k^b$, $S_k(n)\le 2k^n$, and $S_k(n+b)\le 2k^bS_k(n)$.
\end{lemma}

\begin{proof}
The first two are immediate inductions. For the third, apply Lemma~\ref{lem:split} and $\sum_{i<b}k^i\le k^b\le k^bS_k(n)$, valid since $S_k(n)\ge1$.
\end{proof}

\begin{theorem}[Density distortion law]\label{thm:distortion}
If $k\ge2$ and $N_1(n)\le N_2(n+b)$, then $\dens_{N_1}(n)\le 2k^{b}\,\dens_{N_2}(n+b)$.
\end{theorem}

\begin{proof}
$\dens_{N_1}(n)\le N_2(n+b)/S_k(n)$ and $1/S_k(n)\le 2k^b/S_k(n+b)$ by Lemma~\ref{lem:vol}.
\end{proof}

\begin{definition}[Level-$\varepsilon$ critical index]
Given $d:\N\to\R$ and $\varepsilon>0$, an index $c$ is the level-$\varepsilon$ critical index of $d$ if $d(n)<\varepsilon\iff c<n$ for all $n$; that is, $c$ is the last radius at which $d$ is still at level $\varepsilon$.
\end{definition}

\begin{theorem}[Sandwich under multiplicative distortion]\label{thm:sandwich}
Let $d_1,d_2$ satisfy $d_1(n)\le Kd_2(n+b)$ and $d_2(n)\le Kd_1(n+b)$ with $K>0$. Let $c_1$ be the level-$\varepsilon$ index of $d_1$, $c_{\mathrm{lo}}$ the level-$(\varepsilon/K)$ index of $d_2$, and $c_{\mathrm{hi}}$ the level-$(K\varepsilon)$ index of $d_2$. If $b\le c_1$ then
\[
c_{\mathrm{hi}}+b\;\le\;c_1\;\le\;c_{\mathrm{lo}}-b.
\]
\end{theorem}

\begin{proof}
Upper index: $d_1(c_1+1)<\varepsilon$ and $d_2(c_1+1-b)\le Kd_1(c_1+1)<K\varepsilon$, so $c_{\mathrm{hi}}<c_1+1-b$. Lower index: $\varepsilon\le d_1(c_1)\le Kd_2(c_1+b)$ gives $d_2(c_1+b)\ge\varepsilon/K$, hence $c_1+b\le c_{\mathrm{lo}}$.
\end{proof}

\begin{corollary}
With $K=2k^b$ from Theorem~\ref{thm:distortion}, the level-$\varepsilon$ critical index of $\dens_{N_1}$ is sandwiched between the level-$2k^b\varepsilon$ and level-$\varepsilon/(2k^b)$ critical indices of $\dens_{N_2}$, each displaced by $b$.
\end{corollary}

\begin{theorem}[Unbounded critical-index gap]\label{thm:gap}
For every $D\in\N$ there exist antitone $p,q:\N\to\R$ tending to $0$, and $\varepsilon>0$ with $\varepsilon\le p(0)$, $\varepsilon\le q(0)$, such that
\[
p(n)\le 4q(n+1),\qquad q(n)\le 4p(n+1)\qquad(n\in\N)
\]
--- exactly the distortion inequalities of an overhead-$1$ recoding of a binary language, where $K=2\cdot2^1=4$ --- and whose level-$\varepsilon$ critical indices satisfy $c_q+D\le c_p$.
\end{theorem}

\begin{proof}
Take $p(n)=1/(n+1)$, $q(n)=1/(2n+2)$ and $\varepsilon=1/(2D+2)$. Then $4q(n+1)=2/(n+2)\ge 1/(n+1)=p(n)$ and $4p(n+1)=4/(n+2)\ge 1/(2n+2)=q(n)$. Moreover $p(n)<\varepsilon\iff 2D+1<n$, so $c_p=2D+1$, while $q(n)<\varepsilon\iff D<n$, so $c_q=D$; hence $c_p-c_q=D+1$.
\end{proof}

\begin{remark}
The failure is structural. A recoding acts additively on radii and multiplicatively on levels; when the density decays slowly, a fixed multiplicative factor corresponds to an unbounded radial displacement. The level-$\varepsilon$ critical index is therefore not a recoding invariant at any fixed level; the invariants are the count radius and the entropy dimension.
\end{remark}

\section{Uniform transition windows under exact exponential order}

\begin{definition}[Exact exponential order]
$N$ has exact exponential order $a$ with constants $0<c\le C$ if $ca^n\le N(n)\le Ca^n$ for all $n$. We assume throughout $0<a<k$.
\end{definition}

\begin{lemma}[Two-sided density bounds]\label{lem:densbounds}
Let $k\ge2$, $a\ge0$. If $ca^n\le N(n)$ for all $n$ then $\frac{c}{2}(a/k)^n\le \dens_N(n)$; if $N(n)\le Ca^n$ for all $n$ then $\dens_N(n)\le C(a/k)^n$.
\end{lemma}

\begin{proof}
Use $k^n\le S_k(n)\le 2k^n$.
\end{proof}

\begin{theorem}[Cross-system window bound]\label{thm:cross}
Let $k\ge2$, $0<a<k$, $0<c\le C$; suppose $N^{\mathrm{up}}(m)\le Ca^m$ and $ca^m\le N^{\mathrm{low}}(m)$ for all $m$. If $\varepsilon\le\dens_{N^{\mathrm{up}}}(n_+)$ and $\dens_{N^{\mathrm{low}}}(n_-)<\varepsilon$, then
\[
n_+-n_-\;\le\;\frac{\log(2C/c)}{\log(k/a)}.
\]
\end{theorem}

\begin{proof}
If $n_+\le n_-$ the right side is nonnegative ($c\le 2C$) and we are done. Otherwise, by Lemma~\ref{lem:densbounds},
\[
\frac{c}{2}\Bigl(\frac{a}{k}\Bigr)^{n_-}\le \dens_{N^{\mathrm{low}}}(n_-)<\varepsilon\le \dens_{N^{\mathrm{up}}}(n_+)\le C\Bigl(\frac{a}{k}\Bigr)^{n_+},
\]
so $(k/a)^{n_+-n_-}\le 2C/c$; take logarithms and divide by $\log(k/a)>0$.
\end{proof}

\begin{theorem}[Uniform transition window]\label{thm:window}
Let $N$ have exact exponential order $a<k$ with constants $c\le C$. Then for \emph{every} $\varepsilon>0$ and all radii with $\varepsilon\le\dens_N(n_+)$ and $\dens_N(n_-)<\varepsilon$,
\[
n_+-n_-\;\le\;\frac{\log(2C/c)}{\log(k/a)},
\]
a bound independent of $\varepsilon$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:cross} with $N^{\mathrm{up}}=N^{\mathrm{low}}=N$.
\end{proof}

\begin{theorem}[Corrected quasi-invariance of critical indices]\label{thm:corrected}
Let $N_1,N_2$ both have exact exponential order $a<k$ with the same constants $c\le C$, and let $c_i$ satisfy $\varepsilon\le\dens_{N_i}(c_i)$ and $\dens_{N_i}(c_i+1)<\varepsilon$. Then
\[
|c_1-c_2|\;\le\;\frac{\log(2C/c)}{\log(k/a)}+1,
\]
uniformly in $\varepsilon$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:cross} twice, crossing the systems: with upper bound from $N_1$ at $n_+=c_1$ and lower bound from $N_2$ at $n_-=c_2+1$ we get $c_1-c_2-1\le W$; swapping gives $c_2-c_1-1\le W$, where $W=\log(2C/c)/\log(k/a)$.
\end{proof}

\begin{theorem}[Transfer of exponential order across a recoding]\label{thm:transfer}
Assume \eqref{eq:star} and let $N_1$ have exact exponential order $a>0$ with constants $c\le C$. Then $(c/a^{b})a^{m}\le N_2(m)$ for $m\ge b$, and $N_2(m)\le (Ca^{b})a^{m}$ for all $m$.
\end{theorem}

\begin{proof}
For $m\ge b$, $N_2(m)\ge N_1(m-b)\ge ca^{m-b}$. Also $N_2(m)\le N_1(m+b)\le Ca^{m+b}$.
\end{proof}

Feeding Theorem~\ref{thm:transfer} into Theorem~\ref{thm:corrected} gives the index-gap bound $\bigl(\log(2C/c)+2b\log a\bigr)/\log(k/a)+1$, again uniform in $\varepsilon$.

\section{Submultiplicativity supplies the missing lower bound}

A convergent growth rate gives only $N(n)=e^{(L+o(1))n}$, permitting subexponential oscillation --- exactly what prevents a sharp finite crossing. The natural structural hypothesis removes it.

\begin{definition}[Submultiplicativity up to a factor]
$N$ is $P$-submultiplicative ($P\ge1$) if $N(m+n)\le P\,N(m)N(n)$ for all $m,n$. For a finitely generated calculus this expresses that a derivation of length $m+n$ splits, up to bounded bookkeeping, into derivations of lengths $m$ and $n$.
\end{definition}

\begin{theorem}[Fekete bound for derivability counts]\label{thm:fekete}
Let $N(n)\ge1$ for all $n$ and let $N$ be $P$-submultiplicative. Then $L=\lim_n\log N(n)/n$ exists and
\[
e^{Ln}\;\le\;P\,N(n)\qquad\text{for every }n.
\]
\end{theorem}

\begin{proof}
Put $u(n)=\log(PN(n))\ge0$. Then $PN(m+n)\le(PN(m))(PN(n))$, so $u$ is subadditive; by Fekete's lemma $u(n)/n\to\inf_n u(n)/n=:L'$, finite as $u\ge0$. Since $\log N(n)/n=u(n)/n-\log P/n$, we get $L=L'$. Being an infimum, $Ln\le u(n)=\log(PN(n))$ for $n\ge1$, i.e.\ $e^{Ln}\le PN(n)$; the case $n=0$ is trivial.
\end{proof}

\begin{theorem}[Uniform window for submultiplicative counts]\label{thm:submult}
Let $k\ge2$, $P\ge1$, $N(n)\ge1$, $e^{Ln}\le PN(n)$ for all $n$, $N(n)\le C(e^{L})^{n}$ for all $n$, and $e^{L}<k$. Then for every $\varepsilon$ and all radii with $\varepsilon\le\dens_N(n_+)$, $\dens_N(n_-)<\varepsilon$,
\[
n_+-n_-\;\le\;\frac{\log(2CP)}{\log\bigl(k/e^{L}\bigr)}.
\]
\end{theorem}

\begin{proof}
Theorem~\ref{thm:window} with $a=e^{L}$ and $c=P^{-1}\le 1\le C$, since $2C/c=2CP$.
\end{proof}

\section{The dimension spectrum of theorem families}

Every proper family has density zero, so the density cannot distinguish families. The growth rate can.

\begin{definition}
A \emph{stratum} is a cumulative count $N$; it has entropy dimension $h$ if $\log N(n)/n\to h$. The \emph{canonical stratum} of rate $h\ge0$ is $N_h(n)=\lceil e^{hn}\rceil$.
\end{definition}

\begin{lemma}\label{lem:ceil}
$e^{hn}\le N_h(n)\le 2e^{hn}$ and $N_h(n)\ge1$.
\end{lemma}

\begin{proof}
$x\le\lceil x\rceil<x+1$ and $e^{hn}\ge1$.
\end{proof}

\begin{theorem}[Realization of the spectrum]\label{thm:realize}
For every $h\ge0$ the canonical stratum has entropy dimension exactly $h$.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:ceil} gives $h\le \log N_h(n)/n\le h+\log2/n$; squeeze.
\end{proof}

\begin{theorem}[Proper strata sit inside the language at density zero]\label{thm:zero}
If $e^{h}\le k$ then $N_h(n)\le S_k(n)$ for all $n$; if moreover $e^{h}<k$, $k\ge2$, $h\ge0$, then $\dens_{N_h}(n)\to0$.
\end{theorem}

\begin{proof}
$e^{hn}=(e^h)^n\le k^n\le S_k(n)$, and $N_h(n)$ is the least integer above $e^{hn}$. For the density, $N_h(n)\le 2(e^h)^n$, so $\dens_{N_h}(n)\le 2(e^h/k)^n\to0$ by Lemma~\ref{lem:densbounds}.
\end{proof}

Thus $[0,\log k)$ sits entirely inside the zero-density phase: a continuum of distinct strata that the provable/unprovable ratio cannot tell apart.

\begin{theorem}[Union law]\label{thm:union}
If $N_1,N_2\ge1$ have entropy dimensions $h_1,h_2$, then $N_1+N_2$ has entropy dimension $\max(h_1,h_2)$.
\end{theorem}

\begin{proof}
Pointwise $\max(N_1,N_2)\le N_1+N_2\le 2\max(N_1,N_2)$; take logarithms and divide by $n$ to sandwich $\log(N_1+N_2)(n)/n$ between $A(n)=\max(\log N_1(n)/n,\log N_2(n)/n)$ and $A(n)+\log2/n$, then squeeze.
\end{proof}

\begin{definition}[Counting independence]
Strata $A,B$ inside the ambient language \emph{meet independently} if $|A\cap B|_{\le n}\cdot S_k(n)=|A|_{\le n}\cdot|B|_{\le n}$ for all $n$ --- the discrete analogue of $\mathbb{P}(A\cap B)=\mathbb{P}(A)\mathbb{P}(B)$ for the uniform measure on the ball.
\end{definition}

\begin{theorem}[Dimension of an independent intersection]\label{thm:inter}
Let $k\ge2$ and $N_1,N_2,N_\cap\ge1$ satisfy $N_\cap(n)S_k(n)=N_1(n)N_2(n)$ for all $n$, with $N_i$ of entropy dimension $h_i$. Then $N_\cap$ has entropy dimension $h_1+h_2-\log k$.
\end{theorem}

\begin{proof}
Taking logarithms, $\log N_\cap(n)=\log N_1(n)+\log N_2(n)-\log S_k(n)$; divide by $n$ and use $\log S_k(n)/n\to\log k$.
\end{proof}

\begin{lemma}\label{lem:drop}
If $h_1<L$ and $h_2<L$ then $h_1+h_2-L<\min(h_1,h_2)$.
\end{lemma}

\begin{theorem}[Strict dimension drop]\label{thm:strictdrop}
Under the hypotheses of Theorem~\ref{thm:inter}, if $h_1,h_2<\log k$ then $h_\cap<\min(h_1,h_2)$. Equivalently, codimensions $\kappa_i=\log k-h_i$ add: $\kappa_\cap=\kappa_1+\kappa_2$.
\end{theorem}

\begin{theorem}[A nontrivial spectrum exists]\label{thm:spectrum}
Let $k\ge2$ and $0\le h_1<h_2$ with $e^{h_2}<k$. Then the canonical strata of rates $h_1,h_2$ have entropy dimensions $h_1$ and $h_2$, their union has dimension $h_2$, and both have ambient density $0$.
\end{theorem}

\section{Power laws from mixtures of geometric proof regimes}

\begin{definition}
A proof regime of entropy parameter $s>0$ has length tail $T_s(x)=e^{-xs}$: the probability that a random derivable statement is longer than $x$.
\end{definition}

\begin{proposition}[Constant successive ratio]\label{prop:const}
For every $s$ and $x$, $T_s(x+1)/T_s(x)=e^{-s}$, a constant strictly below $1$.
\end{proposition}

A constant successive ratio is the signature of geometric decay, which is never regularly varying: a genuine power law must come from heterogeneity across regimes.

\begin{definition}
The uniform scale mixture is $T(x)=\int_0^1 e^{-xs}\,ds$.
\end{definition}

\begin{theorem}[Closed form]\label{thm:closed}
For $x>0$, $T(x)=\dfrac{1-e^{-x}}{x}$.
\end{theorem}

\begin{proof}
Substitute $t=xs$: $T(x)=\frac1x\int_0^xe^{-t}\,dt$.
\end{proof}

\begin{theorem}[Exact power-law bounds]\label{thm:bounds}
For $x\ge1$, $\dfrac{1-e^{-1}}{x}\le T(x)\le\dfrac1x$.
\end{theorem}

\begin{proof}
From Theorem~\ref{thm:closed}, using $0<e^{-x}\le e^{-1}$ for $x\ge1$.
\end{proof}

\begin{theorem}[Regular variation of index $-1$]\label{thm:rv}
$x\,T(x)\to1$ as $x\to\infty$; hence $T(\lambda x)/T(x)\to\lambda^{-1}$ for every $\lambda>0$.
\end{theorem}

\begin{proof}
$xT(x)=1-e^{-x}\to1$.
\end{proof}

\begin{theorem}[Successive ratios tend to one]\label{thm:ratio}
$T(n+1)/T(n)\to1$ as $n\to\infty$.
\end{theorem}

\begin{proof}
$\frac{T(n+1)}{T(n)}=\frac{1-e^{-(n+1)}}{1-e^{-n}}\cdot\frac{n}{n+1}\to1$.
\end{proof}

\begin{theorem}[The mixture is not geometric]\label{thm:notgeo}
There is no pair $(C,a)$ with $0\le a<1$ such that $T(n)\le Ca^{n}$ for all $n\ge1$.
\end{theorem}

\begin{proof}
Otherwise Theorem~\ref{thm:bounds} gives $1-e^{-1}\le C\,n\,a^{n}$ for all $n\ge1$; but $na^n\to0$ for $a<1$, contradicting positivity of $1-e^{-1}$.
\end{proof}

\begin{remark}
The power law comes entirely from the mixing law near zero entropy: regimes with $s\approx0$ have almost flat tails and dominate at large lengths. The exponent $1$ is the index of the uniform mixing density; a mixing density behaving like $s^{\alpha-1}$ near zero should produce index $\alpha$. Proposition~\ref{prop:const} and Theorem~\ref{thm:ratio} give an operational test: successive tail ratios hovering at a constant below $1$ indicate a single regime, while ratios climbing to $1$ indicate heterogeneity.
\end{remark}

\section{Algorithms}

\begin{algorithmbox}[Empirical transition window]
Given counts $N(0),\dots,N(M)$, alphabet size $k$ and level $\varepsilon$: compute $\dens(n)=N(n)/S_k(n)$; return $n_+=\max\{n\le M:\dens(n)\ge\varepsilon\}$ and $n_-=\min\{n\le M:\dens(n)<\varepsilon\}$. Cost $O(M)$. Theorem~\ref{thm:window} supplies the certified comparison width.
\end{algorithmbox}

\begin{algorithmbox}[Fitted exponential order and certified window]
Estimate $a=\exp(\widehat{\log N(n)/n})$ from the tail; set $c=\min_n N(n)a^{-n}$, $C=\max_n N(n)a^{-n}$ over the fitted range; return $W=\log(2C/c)/\log(k/a)$ when $a<k$. Cost $O(M)$. $W$ bounds the transition width at every level, so an observed width exceeding $W$ certifies failure of the two-sided exponential law on that range.
\end{algorithmbox}

\begin{algorithmbox}[Regime-heterogeneity test]
Given an empirical tail $T$ at integers, compute $\rho(n)=T(n+1)/T(n)$ and $\pi(n)=nT(n)$. If $\rho$ is approximately constant $<1$, report a single geometric regime of entropy $-\log\rho$; if $\rho\nearrow1$ while $\pi$ stabilises, report a scale mixture, regularly varying of index $-1$. Cost $O(M)$.
\end{algorithmbox}

\begin{algorithmbox}[Count-radius comparison across encodings]
Compute $r_i(m)=\min\{n:N_i(n)\ge m\}$ by linear scan and return $\max_m|r_1(m)-r_2(m)|$; by Theorem~\ref{thm:radial} this is at most the recoding overhead, giving an empirical lower bound on it. Cost $O(M+m_{\max})$.
\end{algorithmbox}

\section{Discussion}

\paragraph{Which observables are physical.}
Count radii ($b$-quasi-invariant, Theorem~\ref{thm:radial}) and the entropy dimension (exactly invariant, Theorem~\ref{thm:dim-inv}) are properties of the system. The density at a fixed radius and the critical index at a fixed level (Theorem~\ref{thm:gap}) are properties of the encoding. The mechanism: a recoding of overhead $b$ shifts radii by $b$ and multiplies levels by up to $2k^b$; the two effects become commensurable exactly when the density decays at a definite exponential rate, at the exchange rate $\log(k/a)$ nats of level per unit radius.

\paragraph{Sharpness.}
Theorem~\ref{thm:gap} shows the level rescaling cannot be removed, using profiles that satisfy the distortion inequalities of an actual overhead-$1$ binary recoding; realizing the counterexample by explicit integer counts of a specific calculus remains open. Theorem~\ref{thm:window} needs a two-sided exponential bound \emph{at the same base}: with upper base $a$ and lower base $\rho<a$, the width grows like $\log(1/\varepsilon)/\log(a/\rho)$ and uniformity in $\varepsilon$ is genuinely lost. Fekete's lemma removes half the hypothesis unconditionally for submultiplicative counts; the matching upper bound remains an assumption.

\paragraph{Relation to metric geometry and fractal dimension.}
The setting is a discrete analogue of growth theory for finitely generated groups: a bounded recoding is a quasi-isometry with multiplicative constant $1$, the entropy dimension plays the role of exponential growth rate, and count radii the role of the inverse growth function. Normalising, $h/\log k$ is a box-counting dimension in $[0,1]$ for the corresponding subset of the Cantor-like space of infinite strings, under which Theorem~\ref{thm:union} is the usual maximum law for finite unions and Theorem~\ref{thm:strictdrop} is classical codimension additivity for transversal sets.

\paragraph{Consequences for empirical study of proof corpora.}
Report radii and rates, not densities at fixed cutoffs; certify a window width from the fitted exponential order before claiming a sharp phase transition; and test for heterogeneity, via the successive-ratio diagnostic, before fitting a power law --- since by Proposition~\ref{prop:const} a single regime cannot produce one.

\section{Future work}

\begin{conjecture}[Intrinsic recoding-invariant critical index]
For counts that are monotone and bounded below by $1$, the transferred lower bound of Theorem~\ref{thm:transfer} extends to all radii, and the gap bound $\bigl(\log(2C/c)+2b\log a\bigr)/\log(k/a)+1$ may be replaced by $b+\log(2C/c)/\log(k/a)+1$: the overhead enters additively in radius and not through the entropy factor at all.
\end{conjecture}

\begin{conjecture}[Threshold windows for submultiplicative calculi]
For a finitely generated calculus whose counts are submultiplicative up to a polynomial factor with exponential growth rate strictly below the ambient language, a logarithmically smoothed density is eventually antitone, and every fixed positive level has a transition window of width bounded independently of the cutoff.
\end{conjecture}

\begin{conjecture}[Multifractal spectrum of theorem families]
Partitioning derivable statements by proof-theoretic complexity and assigning each stratum its entropy dimension, natural calculi exhibit a nontrivial multifractal spectrum; the union dimension is the supremum of stratum dimensions, and intersections obey the strict drop of Theorem~\ref{thm:strictdrop} under approximate independence allowing subexponential error factors.
\end{conjecture}

\begin{conjecture}[General mixing laws and a Tauberian converse]
A scale mixture of geometric regimes whose entropy parameter has density proportional to $s^{\alpha-1}$ near zero has a regularly varying tail of index $-\alpha$; conversely, under a Tauberian regularity condition, a regularly varying tail forces the corresponding power behaviour of the mixing law near zero. Theorem~\ref{thm:closed} settles $\alpha=1$ exactly.
\end{conjecture}

\begin{conjecture}[Quantitative diagonalization]
For a concrete arithmetized theory with a fixed prefix-free syntax there are explicit upper and lower bounds on the length of the shortest fixed-point sentence in terms of the description length of the provability predicate, preserved by bounded recodings up to additive constants.
\end{conjecture}

\section{Conclusion}

Reduced to its counting data, a deductive system carries a genuine geometry. Its stable invariants under any bounded change of encoding are radial --- count radii, quasi-invariant with the overhead as additive constant --- and asymptotic --- the entropy dimension, exactly invariant. Density levels are not stable, because recodings distort radii additively but levels multiplicatively by $2k^b$. Where the counting law has a two-sided exponential order below the ambient rate, the mismatch is repaired: transition windows acquire a width bounded uniformly in the level, and critical indices become quasi-invariant with a bound determined by the shape of the counting law rather than the encoding. Submultiplicativity --- the counting shadow of concatenating proofs --- supplies half of that two-sided law unconditionally, with explicit constant $1/P$. Above a single density sits a spectrum: every rate in $[0,\log k]$ realized, unions taking maxima, independent intersections adding codimensions. And heavy-tailed proof-length data cannot come from one homogeneous regime, whose successive ratios are constant, but from a mixture, whose uniform case has the exact tail $(1-e^{-x})/x$.

