"""Algorithm: Certified Level-Independent Transition Window.

Given cumulative derivability counts N(0..M) over a k-letter alphabet, fit the
exponential order of the counts and return the certified transition-window
width W = log(2C/c)/log(k/a), together with the measured windows at a range of
levels.  W bounds the separation between any radius at which the density is
still at level eps and any radius at which it has already dropped below eps,
for EVERY level eps simultaneously.
"""

from __future__ import annotations

import math
from typing import Dict, List, Optional, Sequence, Tuple


def ambient_volume(k: int, n: int) -> int:
    """S_k(n) = 1 + k + ... + k^n, the number of strings of length at most n."""
    return sum(k**i for i in range(n + 1))


def fit_exponential_order(
    counts: Sequence[int], lo: int, hi: int
) -> Tuple[float, float, float]:
    """Fit c a^n <= N(n) <= C a^n on the index window [lo, hi]."""
    a = math.exp(math.log(counts[hi]) / hi)
    ratios = [counts[n] / a**n for n in range(lo, hi + 1)]
    return a, min(ratios), max(ratios)


def certified_window_width(k: int, a: float, c: float, cc: float) -> float:
    """W = log(2C/c) / log(k/a); requires a < k."""
    if not a < k:
        raise ValueError("counts are not exponentially sparse: a >= k")
    return math.log(2 * cc / c) / math.log(k / a)


def measured_separation(counts: Sequence[int], k: int, eps: float) -> Optional[int]:
    """max{n : d(n) >= eps} - min{n : d(n) < eps}, or None if undefined."""
    n_plus: Optional[int] = None
    n_minus: Optional[int] = None
    for n in range(len(counts)):
        d = counts[n] / ambient_volume(k, n)
        if d >= eps:
            n_plus = n
        elif n_minus is None:
            n_minus = n
    if n_plus is None or n_minus is None:
        return None
    return n_plus - n_minus


def certified_window_report(
    counts: Sequence[int], k: int, lo: int, hi: int, levels: Sequence[float]
) -> Dict[str, object]:
    a, c, cc = fit_exponential_order(counts, lo, hi)
    width = certified_window_width(k, a, c, cc)
    measured: List[Tuple[float, Optional[int]]] = [
        (eps, measured_separation(counts, k, eps)) for eps in levels
    ]
    ok = all(m is None or m <= width for _, m in measured)
    return {"a": a, "c": c, "C": cc, "certified_width": width,
            "measured": measured, "consistent": ok}


if __name__ == "__main__":
    counts = [math.ceil(1.5**n) for n in range(90)]
    report = certified_window_report(
        counts, k=2, lo=10, hi=60, levels=[1e-1, 1e-2, 1e-4, 1e-6, 1e-8]
    )
    print(f"fitted order a = {report['a']:.5f}, c = {report['c']:.5f}, "
          f"C = {report['C']:.5f}")
    print(f"certified width = {report['certified_width']:.4f}")
    for eps, m in report["measured"]:
        print(f"  level {eps:.0e}: measured separation {m}")
    print(f"consistent with the certified bound: {report['consistent']}")

"""Algorithm: Count-Radius Invariant Comparison of Two Encodings.

The count radius r(m) = min{ n : N(n) >= m } is the observable dual to a
density level.  Under a bounded recoding of overhead b the two count radii of a
system never differ by more than b, so max_m |r_1(m) - r_2(m)| is a certified
lower bound on the overhead of any translation between the two encodings --- and
a direct test of whether two count tables can describe the same system at all.
"""

from __future__ import annotations

import math
from typing import Dict, List, Optional, Sequence


def count_radius(counts: Sequence[int], m: int) -> Optional[int]:
    """r(m) = min{ n : counts[n] >= m }; None if never reached."""
    lo, hi = 0, len(counts) - 1
    if counts[hi] < m:
        return None
    while lo < hi:                      # binary search: counts is nondecreasing
        mid = (lo + hi) // 2
        if counts[mid] >= m:
            hi = mid
        else:
            lo = mid + 1
    return lo


def radius_profile(counts: Sequence[int], targets: Sequence[int]) -> List[Optional[int]]:
    return [count_radius(counts, m) for m in targets]


def overhead_lower_bound(
    counts1: Sequence[int], counts2: Sequence[int], samples: int = 40
) -> Dict[str, object]:
    """Certified lower bound on the recoding overhead between two encodings."""
    top = min(counts1[-1], counts2[-1])
    if top < 2:
        return {"overhead_lower_bound": 0, "targets": [], "gaps": []}
    targets = sorted({max(1, int(round(2 ** (math.log2(top) * i / samples))))
                      for i in range(samples + 1)})
    gaps: List[int] = []
    for m in targets:
        r1, r2 = count_radius(counts1, m), count_radius(counts2, m)
        if r1 is not None and r2 is not None:
            gaps.append(abs(r1 - r2))
    return {"overhead_lower_bound": max(gaps) if gaps else 0,
            "targets": targets, "gaps": gaps}


if __name__ == "__main__":
    base = [math.ceil(1.6**n) for n in range(70)]
    shifted = [base[max(n - 4, 0)] for n in range(70)]
    result = overhead_lower_bound(base, shifted)
    print("targets :", result["targets"][:8], "...")
    print("gaps    :", result["gaps"][:8], "...")
    print("certified lower bound on the recoding overhead b:",
          result["overhead_lower_bound"])
